const SUPPORTED_LOCALES = ['en', 'es', 'pt-BR', 'zh', 'fr', 'it', 'de', 'ru', 'ko', 'ja', 'hi', 'ca', 'uk', 'ca-valencia', 'eu', 'gl'];

function resolveLocale(raw) {
  if (!raw || typeof raw !== 'string') return null;
  const s = raw.toLowerCase().trim();
  if (s.startsWith('es')) return 'es';
  if (s.startsWith('pt')) return 'pt-BR';
  if (s.startsWith('zh')) return 'zh';
  if (s.startsWith('fr')) return 'fr';
  if (s.startsWith('it')) return 'it';
  if (s.startsWith('de')) return 'de';
  if (s.startsWith('ru')) return 'ru';
  if (s.startsWith('ko')) return 'ko';
  if (s.startsWith('ja')) return 'ja';
  if (s.startsWith('hi')) return 'hi';
  if (s.startsWith('ca') && s.includes('valencia')) return 'ca-valencia';
  if (s.startsWith('ca')) return 'ca';
  if (s.startsWith('eu')) return 'eu';
  if (s.startsWith('gl')) return 'gl';
  if (s.startsWith('uk')) return 'uk';
  if (s.startsWith('en')) return 'en';
  return null;
}

let savedLocale = null;
try {
  savedLocale = localStorage.getItem('trigglow.locale');
} catch (_) {}

const paramLocale = resolveLocale(new URLSearchParams(location.search).get('lang'));
const storageLocale = resolveLocale(savedLocale);
const browserLocale = resolveLocale(navigator.language);

// The app's language lives in the main process (picked here or on the account, else the OS), shared with the tray,
// notifications and the chat dock. localStorage only covers a page without the bridge, and a pick made before the
// main process kept one, which is handed over once (kept on this PC; it does not overwrite the account's).
const i18nShell = window.trigglowShell;
let shellLocale = null;
try {
  shellLocale = i18nShell && i18nShell.locale ? i18nShell.locale() : null;
} catch (_) {}
const mainLocale = resolveLocale(shellLocale && shellLocale.locale);
if (shellLocale && !shellLocale.chosen && storageLocale) i18nShell.setLocale(storageLocale, false).catch(() => {});
let currentLocale =
  paramLocale || (shellLocale && shellLocale.chosen ? mainLocale : storageLocale) || mainLocale || browserLocale || 'en';

window.currentLocale = currentLocale;

window.tr = (key, vars = {}) => {
  const dict = DICT[currentLocale] || DICT.en;
  const tmpl = dict[key] ?? DICT.en[key] ?? key;
  return tmpl.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));
};

function applyTranslations() {
  document.documentElement.lang = currentLocale;
  for (const el of document.querySelectorAll('[data-i18n]')) {
    el.textContent = window.tr(el.dataset.i18n);
  }
  for (const el of document.querySelectorAll('[data-i18n-title]')) {
    el.title = window.tr(el.dataset.i18nTitle);
  }
  for (const el of document.querySelectorAll('[data-i18n-aria]')) {
    el.setAttribute('aria-label', window.tr(el.dataset.i18nAria));
  }
}

window.applyTranslations = applyTranslations;

function useLocale(locale) {
  currentLocale = locale;
  window.currentLocale = locale;
  applyTranslations();
  if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function' && typeof CustomEvent === 'function') {
    window.dispatchEvent(new CustomEvent('localechange', { detail: { locale } }));
  }
}

/** The user picked a language (sign-in screen): the whole app follows, and it is saved to the account. */
window.setLocale = (newLocale) => {
  const resolved = resolveLocale(newLocale) || 'en';
  try {
    localStorage.setItem('trigglow.locale', resolved);
  } catch (_) {}
  if (i18nShell && i18nShell.setLocale) i18nShell.setLocale(resolved).catch(() => {});
  useLocale(resolved);
};

window.getLocale = () => currentLocale;

// Picked somewhere else (another screen, the web dashboard's language menu): follow it, unless the page pinned one.
if (i18nShell && i18nShell.onState && !paramLocale) {
  i18nShell.onState((s) => {
    const next = resolveLocale(s && s.locale);
    if (next && next !== currentLocale) useLocale(next);
  });
}

applyTranslations();
